# frozen_string_literal: true
require 'json'
require 'cgi'
require_relative 'guide_ui'
module PensionGuide
  DATA=JSON.parse(File.read(File.expand_path('../_data/pension-guide.json',__dir__)))
  module_function
  def h(s);CGI.escapeHTML(s.to_s);end
  def source(id,label=nil)
    s=DATA.fetch('sources').find{|x|x['id']==id} || raise(id)
    %(<a href="#{h(s['url'])}" rel="noopener">#{h(label || s['title'])}</a>)
  end
  def hero
    photo=DATA.fetch('photo')
    %(<header class="pension-hero"><div class="pension-hero-copy"><span class="benefit-kicker"><span class="guide-category-symbol">#{GuideUI.icon('document')}</span>LATVIJA · PENSIJU CEĻVEDIS</span><h1>Pensija sākas ar skaidru plānu.</h1><p>Kad var pensionēties, kā pārbaudīt savu stāžu un kurā dienā gaidīt izmaksu? Vienuviet vecuma datuma rīks, pieteikšanās ceļš un oficiālie avoti par pensiju Latvijā.</p><div class="benefit-actions"><a class="benefit-button" href="#pensijas-vecums">Kad varu pensionēties? #{GuideUI.icon('arrow')}</a><a href="#izmaksas">Meklēju izmaksas datumu #{GuideUI.icon('down')}</a></div><div class="pension-hero-note">#{GuideUI.icon('shield')}<span>Pašreizējie noteikumi, saprotami soļi.<br>Pārbaudīts 15.11.2026.</span></div></div><figure class="pension-hero-photo"><img src="#{h(photo['src'])}" srcset="#{h(photo['srcset'])}" sizes="(max-width: 850px) 100vw, 50vw" width="800" height="1200" alt="#{h(photo['alt'])}" fetchpriority="high" decoding="async"><div class="pension-photo-label"><span>LAIKS NĀKAMAJAI NODAĻAI</span><strong>Savam ritmam.<br>Saviem plāniem.</strong></div><figcaption>#{h(photo['caption'])} <a href="/pilsetas-un-fotografijas/#pensiju-foto">Foto licence</a></figcaption></figure></header><div class="pension-key-facts" aria-label="Pensijas plānošanas pamatnosacījumi"><div><strong>65<span>gadi</span></strong><p>Vispārējais pensijas vecums</p></div><div><strong>20<span>gadi</span></strong><p>Minimālais apdrošināšanas stāžs</p></div><div><strong>1<span>mēnesis</span></strong><p>Agrākais pieteikšanās laiks pirms vecuma robežas</p></div><a href="#pensiju-veidi">Īpašie gadījumi<br>un priekšlaicīgā pensija #{GuideUI.icon('arrow')}</a></div>)
  end
  def calculator
    %(<section class="pension-calculator" id="pensijas-vecums" data-pension-calculator><header><div><span class="benefit-kicker">VECUMA ROBEŽAS DATUMS</span><h2>Kad es varu pensionēties?</h2></div><p>Rīks izmanto pašreizējo vispārējo 65 gadu vecumu. Tas neaprēķina pensijas summu un neapstiprina tiesības uz pensiju.</p></header><div class="pension-calc-grid"><form><label>Dzimšanas datums<input type="date" name="birth" min="1900-01-01" required></label><label>Apdrošināšanas stāžs gados <small>Ja zināms; vari atstāt tukšu</small><input type="number" name="service" min="0" max="80" step="0.1" inputmode="decimal" placeholder="Piemēram, 32"></label><button class="benefit-button" type="submit">Aprēķināt vecuma datumus #{GuideUI.icon('arrow')}</button><p>Dati paliek šajā lapā. Dzimšanas datumu nesaglabājam pārlūkā un nepievienojam adresei.</p></form><div class="pension-calc-output" aria-live="polite" data-pension-output><div class="pension-empty-heading"><span class="pension-output-icon">#{GuideUI.icon('calendar')}</span><span>TAVS PERSONĪGAIS LAIKA PLĀNS</span></div><div class="pension-age-track" aria-label="Vecuma robežu skaidrojums"><div class="pension-age-start">#{GuideUI.icon('document')}<small>Dzimšanas<br>datums</small></div><div><strong>63<small>gadi</small></strong><span>Priekšlaicīgi</span></div><div><strong>65<small>gadi</small></strong><span>Vispārējais vecums</span></div></div><h3>Atrodi savus datumus</h3><p>Ievadi dzimšanas datumu, lai redzētu abas vecuma robežas savā kalendārā. Pēc aprēķina vari lejupielādēt arī atgādinājumu pieteikuma pārbaudei.</p><div class="pension-empty-note">#{GuideUI.icon('shield')}<span>Stāžu un tiesības apstiprina VSAA.<br>Aprēķins paliek tikai šajā lapā.</span></div></div></div><p class="pension-rule-note">#{source('age','VSAA noteikumi')}: 65 gadi un vismaz 20 gadu stāžs; priekšlaicīgi 63 gadi un vismaz 30 gadu stāžs. Īpašās grupas šis rīks nevērtē.</p></section>)
  end
  def page(reminder)
    cohort=(2026..2030).map{|y|"<tr><th scope=\"row\">#{y}</th><td>#{y-65}</td><td>65 gadi</td><td>Vismaz 20 gadi</td></tr>"}.join
    faq=DATA['faq'].map{|q,a|"<details><summary>#{h(q)}</summary><p>#{h(a)}</p></details>"}.join
    %(<article class="benefit-guide pension-guide" data-pension-guide>#{hero}<nav class="benefit-subnav" aria-label="Pensiju ceļveža sadaļas"><a href="#pensijas-vecums">Vecuma rīks</a><a href="#pensiju-veidi">Pensiju veidi</a><a href="#pieteiksanas">Pieteikšanās</a><a href="#izmaksas">Izmaksas</a><a href="#pensiju-limeni">Uzkrājumi</a></nav>#{calculator}
    <section class="pension-section" id="pensiju-veidi"><span class="benefit-kicker">SĀC AR SAVU SITUĀCIJU</span><h2>Parastā, priekšlaicīgā vai cita pensija?</h2><div class="pension-paths"><article><span class="pension-path-icon">#{GuideUI.icon('calendar')}</span><small>VISPĀRĒJĀ KĀRTĪBA</small><h3>Vecuma pensija</h3><strong>65 gadi <span>+ 20 gadu stāžs</span></strong><p>Vecums un apdrošināšanas stāžs ir divas atsevišķas prasības. Pensijas apmēru nosaka individuāli; dzimšanas gads vien summu nepasaka.</p>#{source('age','Nosacījumi un pieteikums')}</article><article><span class="pension-path-icon">#{GuideUI.icon('document')}</span><small>JĀIZVĒRTĒ SEKAS</small><h3>Priekšlaicīga pensija</h3><strong>63 gadi <span>+ 30 gadu stāžs</span></strong><p>Līdz 65 gadu vecumam nestrādājošam saņēmējam izmaksā 50% no piešķirtā apmēra. Ja cilvēks kļūst par obligāti apdrošinātu darba ņēmēju vai pašnodarbināto, šo pensiju pagaidām neizmaksā.</p>#{source('overview','Priekšlaicīgās pensijas ierobežojumi')}</article><article><span class="pension-path-icon">#{GuideUI.icon('shield')}</span><small>INDIVIDUĀLA PĀRBAUDE</small><h3>Īpašie gadījumi</h3><strong>Citi nosacījumi</strong><p>Atvieglojumi bērnu aprūpētājiem, politiski represētām personām un citām likumā noteiktām grupām jāpārbauda atsevišķi. Invaliditātes, izdienas un apgādnieka zaudējuma pensijai ir sava kārtība.</p>#{source('law','Pārbaudīt likuma nosacījumus')}</article></div><aside class="pension-warning"><b>Priekšlaicīgā pensija ir ilgtermiņa lēmums.</b><p>Sasniedzot vispārējo vecumu, to nepiešķir no jauna mainās izmaksas nosacījumi. Pirms izvēles noskaidro arī ietekmi uz bezdarbnieka pabalstu un citiem maksājumiem.</p></aside></section>
    <section class="pension-section"><span class="benefit-kicker">2026–2030</span><h2>Kurā gadā aprit 65 gadi?</h2><p>Tabula ir dzimšanas gada orientieris pēc pašreizējā noteikuma. Precīzais vecuma robežas datums ir dzimšanas dienā; tas nav apstiprināts pensijas piešķiršanas vai izmaksas datums.</p><div class="benefit-table-scroll"><table class="pension-table"><thead><tr><th>Gads</th><th>Dzimšanas gads</th><th>Vispārējais vecums</th><th>Stāža prasība</th></tr></thead><tbody>#{cohort}</tbody></table></div></section>
    <section class="pension-section" id="pieteiksanas"><span class="benefit-kicker">NO DOKUMENTIEM LĪDZ LĒMUMAM</span><h2>Kā pieteikties pensijai?</h2><ol class="pension-steps"><li><span>01</span><div><h3>Pārbaudi reģistrēto stāžu</h3><p>Darba gadi ne vienmēr sakrīt ar VSAA reģistrēto apdrošināšanas stāžu. Par periodiem līdz 1996. gadam var būt vajadzīga darba grāmatiņa, arhīva izziņa vai citi pierādījumi. #{source('service','Stāža reģistrēšanas kārtība')} palīdz sagatavot tieši attiecīgos dokumentus.</p></div></li><li><span>02</span><div><h3>Noskaidro prognozi un 2. līmeņa izvēli</h3><p>#{source('forecast','VSAA individuālā prognoze')} pieejama ne agrāk kā piecus gadus pirms pensijas vecuma. Tajā nav 2. līmeņa kapitāla, atvieglojumu un garantēto minimumu. Pārbaudi šīs daļas atsevišķi.</p></div></li><li><span>03</span><div><h3>Iesniedz pieteikumu pareizajā laikā</h3><p>VSAA norāda: pensiju var pieprasīt ne agrāk kā mēnesi pirms noteiktā vecuma sasniegšanas. Elektronisko pieteikumu sāc no #{source('age','oficiālā pakalpojuma')}; iespējama arī klātiene un citi tajā uzskaitītie veidi. Ja piesakies vēlāk, atpakaļejošais periods ir ierobežots.</p></div></li><li><span>04</span><div><h3>Izlasi piešķirto periodu un izmaksas kārtību</h3><p>Lēmumā pārbaudi sākuma datumu, izmantoto stāžu, summu un saņemšanas veidu. Ja kaut kas nesakrīt ar taviem dokumentiem, precizē to VSAA. Pirmais pārskaitījums un vēlākā regulārā izmaksa var atšķirties.</p></div></li></ol><div class="pension-documents"><h3>Pirms pieteikuma sagatavo</h3><ul><li>Personu apliecinošu dokumentu un izvēlēto saziņas veidu.</li><li>Stāža pierādījumus par periodiem, kuru nav VSAA datos.</li><li>Sava konta informāciju un izvēli par 2. līmeņa kapitālu.</li><li>Ziņas par darba un apdrošināšanas periodiem ārvalstīs, ja tādi ir.</li></ul><a class="benefit-button" href="#{h(DATA['sources'].first['url'])}">Atvērt VSAA pieteikšanās informāciju #{GuideUI.icon('external')}</a></div></section>
    <section class="pension-section" id="izmaksas"><span class="benefit-kicker">TAVS LĒMUMS, TAVS DATUMS</span><h2>Kad izmaksā pensiju Latvijā?</h2><div class="pension-payment-grid"><div><h3>Viena izmaksas datuma visiem nav</h3><p>#{source('payment','Izmaksas kārtība')} paredz, ka datumu nosaka VSAA atbilstoši saņemšanas veidam. Sāc ar savu lēmumu, nevis citas personas bankas pārskaitījumu. Bankas konta vai piegādes adreses maiņu piesaki VSAA.</p><h3>Svētki un pirmais maksājums</h3><p>Pirms svētkiem skati jaunāko VSAA paziņojumu par konkrēto periodu. Vecas pirmssvētku ziņas nav nākamā gada grafiks. Ja gaidītā izmaksa nav saņemta, sazinies ar #{source('contact','VSAA konsultāciju centru')}, norādot attiecīgo mēnesi.</p><p>Pievieno atgādinājumu tikai pēc sava datuma pārbaudes. Lejupielādētais kalendārs neiesniedz pieteikumu VSAA un nepaziņo par iestādes izmaiņām automātiski.</p></div><aside class="pension-payment-note"><div class="pension-calendar-emblem" aria-hidden="true"><span>MANS KALENDĀRS</span>#{GuideUI.icon('calendar')}<i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><h3>Atzīmē savā kalendārā</h3><p>Personīgais datums, pārbaudes atgādinājums un ICS fails Apple, Google vai Outlook kalendāram.</p><a class="benefit-button" href="#pensijas-atgadinajums">Izveidot atgādinājumu #{GuideUI.icon('down')}</a></aside></div><div id="pensijas-atgadinajums">#{reminder}</div></section>
    <section class="pension-section" id="pensiju-limeni"><span class="benefit-kicker">VIENA PENSIJA, DAŽĀDAS DAĻAS</span><h2>Kā atšķiras trīs pensiju līmeņi?</h2><div class="pension-levels"><article><span>1</span><h3>Valsts pensijas pamats</h3><p>To veido uzskaitītais pensijas kapitāls un likumā paredzētais aprēķins. Prognoze nav pēdējās neto algas fiksēts procents.</p>#{source('forecast','Pārbaudīt VSAA prognozi')}</article><article><span>2</span><h3>Ieguldītais pensijas kapitāls</h3><p>Pensionējoties to var pievienot valsts pensijai vai izmantot mūža pensijas apdrošināšanai, ja izpildīti nosacījumi. Salīdzini VSAA piedāvātās iespējas un līguma noteikumus.</p>#{source('second','2. līmeņa kapitāla izmantošana')}</article><article><span>3</span><h3>Brīvprātīgs papildu uzkrājums</h3><p>Privātā plāna izmaksas vecums parasti nav agrāks par 55 gadiem. Tas nedod tiesības uz valsts vecuma pensiju 55 gados. Pārbaudi konkrētā plāna izmaksas un komisijas.</p>#{source('third','Latvijas Bankas skaidrojums')}</article></div></section>
    <section class="pension-section pension-two-columns"><div><span class="benefit-kicker">SUMMA UN NODOKLIS</span><h2>Kāpēc piešķirtais un saņemtais apmērs atšķiras?</h2><p>2026. gadā pensionāra neapliekamais minimums ir 1000 eiro mēnesī. Strādājot tā piemērošana atkarīga no algas nodokļa grāmatiņas: iespējams sadalījums 500 eiro pensijai un 500 eiro algai. Precīzo piemērošanu pārbaudi #{source('tax','VID skaidrojumā')} un savā EDS.</p><p>Minimālā pensija arī nav viena summa visiem. #{source('minimum','VSAA 2026. gada tabula')} to saista ar apdrošināšanas stāžu un noteiktām personu grupām. Tā pati par sevi neaizstāj tiesību izvērtēšanu.</p></div><div><span class="benefit-kicker">PĀRSKATĪŠANA</span><h2>Indeksācija un pārrēķins nav viens un tas pats</h2><p>#{source('index','2026. gada 1. oktobra indeksācija')} attiecas uz līdz 30. septembrim piešķirtām vai pārrēķinātām pensijām. Vispārējā indeksējamā robeža ir 1589 eiro, bet noteiktām grupām indeksē visu apmēru. Jaunu iesniegumu indeksācijai parasti nevajag.</p><p>Ja pēc pensionēšanās turpini strādāt un tiek veiktas iemaksas, aktuālo automātiskā pārrēķina kārtību skati #{source('overview','Labklājības ministrijas pārskatā')}. Tas neizveido jaunu kopīgu pensijas izmaksas datumu.</p></div></section>
    <section class="pension-section"><span class="benefit-kicker">DARBS VAIRĀKĀS VALSTĪS</span><h2>Ja esi strādājis vai dzīvo ārpus Latvijas</h2><p>Sagatavo valstis, darba periodus un ārvalstu apdrošināšanas numurus. ES sociālās drošības koordinācija var palīdzēt ņemt vērā vairāku valstu periodus tiesību noteikšanai, taču katra valsts aprēķina savu daļu un piemēro savu pensionēšanās vecumu. Latvijas 65 gadu datums neapstiprina citas valsts pensijas sākumu.</p><p>#{source('abroad','VSAA pārskats par pensijām ES')} skaidro pieteikšanu un saņemšanas turpināšanu. Pārceļoties precizē, kādus dzīvesvietas un citus apliecinājumus vajadzēs iesniegt; nepārtrauc saziņu pēc pirmā maksājuma.</p></section>
    <section class="benefit-faq"><h2>Bieži jautājumi par pensiju</h2>#{faq}</section><section class="pension-section"><h2>Ja meklē citu pensiju vai papildu atbalstu</h2><p>Strādā arī pēc pensionēšanās? <a href="/nodoklu-kalkulators/">Algas un nodokļu kalkulatorā</a> salīdzini darba algas IIN, sociālās iemaksas un 500 eiro dalītā minimuma piemērošanu.</p><nav class="pension-other" aria-label="Citi pensiju pakalpojumi"><a href="https://www.vsaa.gov.lv/lv/pakalpojumi/invaliditates-pensijas-pieskirsana-un-izmaksasana">Invaliditātes pensija #{GuideUI.icon('external')}</a><a href="https://www.vsaa.gov.lv/lv/pakalpojumi/izdienas-pensijas-pieskirsana-un-izmaksasana">Izdienas pensija #{GuideUI.icon('external')}</a><a href="https://www.vsaa.gov.lv/lv/pakalpojumi/apgadnieka-zaudejuma-pensijas-pieskirsana-un-izmaksasana">Apgādnieka zaudējuma pensija #{GuideUI.icon('external')}</a><a href="/pabalstu-izmaksas/majokla-pabalsts/">Mājokļa pabalsta ceļvedis #{GuideUI.icon('arrow')}</a><a href="/pabalstu-izmaksas/gmi-pabalsts/">GMI pabalsta ceļvedis #{GuideUI.icon('arrow')}</a><a href="/pabalstu-izmaksas/">Visi sociālā atbalsta ceļveži #{GuideUI.icon('arrow')}</a></nav></section></article>)
  end
  def notes
    {'heading'=>'Pensijas plāns un individuālais lēmums','paragraphs'=>['Pensijas plānošanā nodali vecuma robežu, apdrošināšanas stāžu un izmaksas datumu. Šīs lapas datuma rīks izmanto pašreizējo vispārējo pensionēšanās vecumu, bet nelemj par īpašajiem gadījumiem, ārvalstu periodiem vai tiesībām saņemt noteiktu summu. Saglabā dokumentus un pārbaudi datus oficiālajā VSAA pakalpojumā.','Ja pensija jau piešķirta, regulāro saņemšanas dienu pārbaudi savā lēmumā. Kalendāra atgādinājums palīdz sekot personīgajam plānam, bet neaizstāj iestādes paziņojumu un nepasaka, ka izmaksa jau veikta. Par nodokli, indeksāciju un pārrēķinu izmanto katram jautājumam atbilstošo pirmavotu.'],'icon'=>'calculator','sources'=>DATA['sources'].first(3),'related'=>[{'url'=>'/pabalstu-izmaksas/','title'=>'Sociālā atbalsta ceļveži'},{'url'=>'/pabalstu-izmaksas/majokla-pabalsts/','title'=>'Mājokļa atbalsts'}]}
  end
end
